class Solution {
    public String fixSpaces(String text) {
    String[] words = text.split(" ");
        String res = "";
        for (int i = 0; i < words.length; i++) {
            if (words[i].equals("")) {
                continue;
            }
            res += words[i];
            if (i < words.length - 1) {
                if (words[i + 1].equals("")) {
                    res += "-";
                } else {
                    res += "_";
                }
            }
        }
        return res;
}

