    public List<List<Integer>> getRow(List<List<Integer>> lst, int x) {
    // x is int
        // lst is list
        // return list of tuples (row, column)
        // 0-indexed
        // first sort by row, then sort by column
        // if equal rows, sort row by column DESC
        // return [] if no match
        ArrayList<Pair<Integer, Integer>> result = new ArrayList<>();
        for (int i = 0; i < lst.size(); i++) {
            for (int j = 0; j < lst.get(i).size(); j++) {
                if (lst.get(i).get(j) == x) {
                    result.add(new Pair<>(i, j));
                }
            }
        }
        // sort by row ascending
        Collections.sort(result, new Comparator<Pair<Integer, Integer>>() {
            @Override
            public int compare(Pair<Integer, Integer> o1, Pair<Integer, Integer> o2) {
                return o1.getValue0().compareTo(o2.getValue0());
            }
        });
        // sort by col descending
        Collections.sort(result, new Comparator<Pair<Integer, Integer>>() {
            @Override
            public int compare(Pair<Integer, Integer> o1, Pair<Integer, Integer> o2) {
                return o2.getValue1().compareTo(o1.getValue1());
            }
        });
        return result;
}

