    public double median(List<Integer> l) {
    // Insert the elements of l into a sorted list
        ArrayList<Integer> sortedList = new ArrayList<Integer>();
        for (int i = 0; i < l.size(); i++) {
            int number = l.get(i);
            if (sortedList.size() == 0) {
                sortedList.add(number);
            } else {
                int j = 0;
                while (j < sortedList.size() && number > sortedList.get(j)) {
                    j++;
                }
                sortedList.add(j, number);
            }
        }
        // Return the median
        if (sortedList.size() % 2 == 0) {
            return (sortedList.get(sortedList.size() / 2) + sortedList.get(sortedList.size() / 2 - 1)) / 2f;
        } else {
            return sortedList.get(sortedList.size() / 2);
        }
}

