class Solution {
    public int maxFill(List<List<Integer>> grid, int capacity) {
    // for each row, count
        // the number of 1's and
        // their distance from each other.
        // then calculate the number of buckets
        // required to fill all the 1's
        // this is done by taking the largest bucket count
        // for all the 1's in a row and multiplying it
        // by the number of rows.
        // this accounts for all the 1's 
        // and then we add the number of rows
        // to account for the rows without 1's
        int times = 0;
        int rows = grid.size();
        int cols = grid.get(0).size();
        for (int i = 0; i < rows; i++) {
            int capacity_left = capacity;
            for (int j = 0; j < cols; j++) {
                if (grid.get(i).get(j) == 1) {
                    if (capacity_left == 0) {
                        times++;
                        capacity_left = capacity;
                    }
                    capacity_left--;
                }
            }
            times++;
        }
        return times;
}

