    public int maxFill(List<List<Integer>> grid, int capacity) {
    int num_tries = 0;
        for (ArrayList<Integer> row : grid) {
            if (row.size() > capacity) {
                System.out.println("no capacity: " + row);
                return -1;
            }
            int sum = row.stream().mapToInt(i -> i).sum();
            int water_to_remove = sum / capacity;
            // tricky part: if mod = 0, then it fills the bucket perfectly and 
            // the number of operations required is just the water_to_remove.
            // If mod > 0, then it fills the bucket +1, so it requires water_to_remove + 1
            // operations.
            num_tries += sum % capacity == 0 ? water_to_remove : water_to_remove + 1;
        }
        return num_tries;
}

