class Solution {
    public int smallestChange(List<Integer> arr) {
    int n = arr.size();
        int[][] minChange = new int[n][n];
        int[][] palindrome = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) {
                    minChange[i][j] = 0;
                    palindrome[i][j] = 1;
                } else {
                    minChange[i][j] = -1;
                    palindrome[i][j] = 0;
                }
            }
        }
        for (int d = 1; d < n; d++) {
            for (int i = 0; i < n - d; i++) {
                int j = i + d;
                minChange[i][j] = minChange(i, j, minChange, palindrome, arr);
                palindrome[i][j] = palindrome(i, j, minChange, palindrome, arr);
            }
        }
        return minChange[0][n - 1];
}

