class Solution {
    public boolean isPrime(int n) {
    // If a number is less than 2, it's not prime, so return false
        if (n < 2) {
            return false;
        }
        // We only need to check up to the square root of the number for factors
        for (int i = 2; i <= Math.sqrt(n); i++) {
            // If n is divisible by i, it has a factor other than 1 and itself,
            // so it is not prime, so return false
            if (n % i == 0) {
                return false;
            }
        }
        // If we didn't find any factors, the number is prime, so return true
        return true;
}

