            int n = (int) s.charAt(i);
            // if n is either 90, 122, or a letter after 122 (ie, the one after z),
            if (n == 90 || n == 122 || n > 122) {
                // set n to itself minus 23
                n -= 23;
            }
            // otherwise,
            else {
                // set n to itself plus 3
                n += 3;
            }
            // concatenate the letter of n to enc
            enc += (char) n;
        }
        // return enc
        return enc;
}

