class Solution {
    public String stringXor(String a, String b) {
    // Note: StringBuilder is used to efficiently build strings.
        StringBuilder output = new StringBuilder();
        int length = Math.max(a.length(), b.length());
        // Pad shorter string with zeros.
        a = String.format("%0" + length + "d", Integer.parseInt(a));
        b = String.format("%0" + length + "d", Integer.parseInt(b));
        for (int i = 0; i < length; i++) {
            // Perform XOR for current digit.
            if (a.charAt(i) == b.charAt(i)) {
                output.append('0');
            } else {
                output.append('1');
            }
        }
        return output.toString();
}

