class Solution {
    public List<Integer> maximum(List<Integer> arr, int k) {
    // With an arraylist, add the first k elements.
        // Sort the arraylist.
        // for each element in the array, compare it to the last element of the
        // arraylist, and replace it if the element is greater.
        // The arraylist is now sorted, so the last k elements are the greatest
        // k elements in the array.
        ArrayList<Integer> result = new ArrayList<>();
        if (arr.size() == 0) {
            return result;
        }
        for (int i = 0; i < k; i++) {
            result.add(arr.get(i));
        }
        Collections.sort(result);
        for (int i = k; i < arr.size(); i++) {
            int end = result.size() - 1;
            if (arr.get(i) > result.get(end)) {
                result.remove(end);
                result.add(arr.get(i));
                Collections.sort(result);
            }
        }
        return result;
}

