import java.lang.*;

class Solution {
    public List<Integer> maximum(List<Integer> arr, int k) {
    // The idea is to use a k-size heap to store the biggest k elements.
        // However, it is not straight-forward to use a max-heap to store the
        // smallest k elements.
        // Thus, we can use a min-heap to store the biggest k elements in the
        // following way:
        // Pop the min element.
        // Then, push the maximum element of the remaining elements.
        Comparator<Integer> comparator = (Integer x, Integer y) -> Integer.compare(x, y);
        PriorityQueue<Integer> queue = new PriorityQueue<>(k, comparator);
        int end = arr.size();
        int start = 0;
        while (start < end) {
            int max = arr.get(start);
            for (int i = start + 1; i < end; i++) {
                int current = arr.get(i);
                if (current > max) {
                    max = current;
                }
            }
            if (queue.size() < k) {
                queue.add(max);
            } else {
                if (queue.peek() < max) {
                    queue.poll();
                    queue.add(max);
                }
            }
            start++;
        }
        ArrayList<Integer> result = new ArrayList<>(k);
        while (!queue.isEmpty()) {
            result.add(queue.poll());
        }
        return result;
}

