class Solution {
    public List<Integer> maximum(List<Integer> arr, int k) {
    // Edge cases
        if (arr == null || arr.size() == 0) return new ArrayList<Integer>();
        if (k == 0) return new ArrayList<Integer>();
        // Using a double ended queue
        ArrayDeque<Integer> deque = new ArrayDeque<Integer>();
        for (int i : arr) {
            // Inserting the first element
            if (deque.size() == 0) {
                deque.addLast(i);
            } else {
                // If the number is less than the first element do nothing.
                if (i < deque.getFirst()) {
                    // do nothing
                } else {
                    // If the number is greater than the first element remove all the 
                    // numbers until the number is less than the current element or the
                    // queue is empty.
                    while (deque.size() > 0 && i > deque.getLast()) {
                        deque.removeLast();
                    }
                    // Remove the first element if the size is equal to k.
                    if (deque.size() == k) {
                        deque.removeFirst();
                    }
                    // If the queue is still not empty then add the current element to the
                    // queue.
                    if (deque.size() < k) {
                        deque.addLast(i);
                    }
                }
            }
        }
        // Return the queue converted to an array list.
        return new ArrayList<Integer>(deque);
}

