class Solution {
    public List<Integer> maximum(List<Integer> arr, int k) {
    assert (arr.size() >= k);
        // Hash-based algorithm. Use a priority queue to store the top K elements.
        // Use a hash to store whether an element is in the priority queue or not.
        // O(n log k) time and O(k) space.
        // Since every element is retrieved (and polled) at most once,
        // the time complexity is O(n log k).
        PriorityQueue<Integer> q = new PriorityQueue<>(k);
        HashSet<Integer> set = new HashSet<>();
        for (int i = 0; i < arr.size(); i++) {
            int e = arr.get(i);
            if (set.contains(e)) continue;
            set.add(e);
            if (q.size() < k) {
                q.add(e);
            } else {
                if (e > q.peek()) {
                    q.poll();
                    q.add(e);
                }
            }
        }
        ArrayList<Integer> result = new ArrayList<>();
        while (!q.isEmpty()) {
            result.add(q.poll());
        }
        return result;
}

