class Solution {
    public List<String> listSort(List<String> lst) {
    ArrayList<String> result = new ArrayList<String>();
        if (lst.size() == 0) return result;
        int max = 0;
        int count = 0;
        int temp_length = 0;
        int size = lst.size();
        ArrayList<String> temp = new ArrayList<String>();
        // get max length
        for (int i = 0; i < size; i++) {
            temp_length = lst.get(i).length();
            if (temp_length % 2 == 0) {
                if (temp_length > max) max = temp_length;
            }
        }
        // get count
        for (int i = 0; i < size; i++) {
            temp_length = lst.get(i).length();
            if (temp_length == max) count++;
        }
        // sort list
        for (int i = 0; i < size; i++) {
            temp_length = lst.get(i).length();
            if (temp_length == max) {
                temp.add(lst.get(i));
            }
        }
        Collections.sort(temp);
        // add to result
        for (int i = 0; i < count; i++) {
            result.add(temp.get(i));
        }
        return result;
}

