class Solution {
    public List<Integer> sortThird(List<Integer> l) {
    ArrayList<Integer> l_copy = new ArrayList<Integer>(l);
        int num_entries = l.size();
        ArrayList<Integer> l_split = new ArrayList<Integer>();
        ArrayList<Integer> l_not_split = new ArrayList<Integer>();
        // split l into a sublist l_split of the elements at the indicies of l that are divisible by three, and l_not_split which is the rest of l.
        for (int i = 0; i < num_entries; i++) {
            if (i % 3 == 0) {
                l_split.add(l.get(i));
            } else {
                l_not_split.add(l.get(i));
            }
        }
        // sort l_split
        Collections.sort(l_split);
        // write l_split back into l_copy
        int split_index = 0;
        for (int i = 0; i < num_entries; i++) {
            if (i % 3 == 0) {
                l_copy.set(i, l_split.get(split_index));
                split_index += 1;
            }
        }
        return l_copy;
}

