class Solution {
    public List<Integer> sortThird(List<Integer> l) {
    if (l.size() < 3) return l;
        // The two lists to be zipped together
        ArrayList<Integer> l1 = new ArrayList<Integer>();
        ArrayList<Integer> l2 = new ArrayList<Integer>();
        // Traverse the list
        for (int i = 0; i < l.size(); i++) {
            // If the index is divisible by three, then the value should be sorted
            if (i % 3 == 0) {
                l1.add(l.get(i));
                // Sort the values in l1
                Collections.sort(l1);
                // Retrieve the value at index 0 of l1 and add it to l2
                l2.add(l1.get(0));
                // Clear l1
                l1.clear();
            }
            // If the index is not divisible by three, then the value should be the same as the value in l
            else {
                l2.add(l.get(i));
            }
        }
        return l2;
}

