class Solution {
    public boolean checkIfLastCharIsALetter(String txt) {
    // Given a string, return true if the last character is an alphabetical character and is not a part of a word and false otherwise.
        // A "word" is a group of characters separated by space.
        // Examples:
        // checkIfLastCharIsALetter("apple pie") ➞ false
        // checkIfLastCharIsALetter("apple pi e") ➞ true
        // checkIfLastCharIsALetter("apple pi e ") ➞ false
        // checkIfLastCharIsALetter("") ➞ false
        if (txt.equals("")) return false;
        if (txt.endsWith(" ")) return false;
        String[] words = txt.split(" ");
        String lastWord = words[words.length - 1];
        String lastChar = lastWord.substring(lastWord.length() - 1);
        return lastChar.matches("[a-zA-Z]");
}

