    public boolean moveOneBall(List<Integer> arr) {
    if (arr.size() <= 1) {
            return true;
        }
        // We store the array in a list so we can rotate it.
        List<Integer> list = new ArrayList<Integer>(arr);
        int max = Collections.max(list);
        for (int i = 0; i < list.size(); i++) {
            int temp = Collections.max(list);
            if (temp < max) {
                return false;
            }
            max = temp;
            // Rotate list
            Collections.rotate(list, 1);
        }
        return true;
}

