class Solution {
    public boolean moveOneBall(List<Integer> arr) {
    // use a priority queue
        int[] count = new int[arr.size()];
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int i : arr) {
            pq.add(i);
        }
        for (int i = 0; i < arr.size(); i++) {
            // get the next smallest element
            int next = pq.poll();
            if (arr.get(i) != next) {
                // if the smallest element is not in the correct position, then
                // we need to swap
                for (int j = 0; j < arr.size(); j++) {
                    if (arr.get(j) == next) {
                        // swap the elements
                        int temp = arr.get(i);
                        arr.set(i, arr.get(j));
                        arr.set(j, temp);
                        count[j]++;
                        // if the element has already been swapped twice, then
                        // it is not possible to sort the array
                        if (count[j] == 2) {
                            return false;
                        }
                        break;
                    }
                }
            }
        }
        return true;
}

