class Solution {
    public boolean checkDictCase(Map<Object, Object> dict) {
    if (dict.isEmpty()) {
            return false;
        }

        // get the first key and determine if it is uppercase or lowercase
        String firstKey = dict.keySet().iterator().next();
        boolean isFirstUpper = firstKey.toUpperCase().equals(firstKey);

        // check all the keys to determine if they all match the first key
        for (String key : dict.keySet()) {
            if (isFirstUpper && !key.toUpperCase().equals(key)) {
                return false;
            } else if (!isFirstUpper && !key.toLowerCase().equals(key)) {
                return false;
            }
        }

        return true;
}

