            if (year < 1900) return false;
            // day must be between 1 and 31 inclusive and must be less than the number of days allowed in the month
            if (day < 1 || day > 31) return false;
            if (month == 2) {
                // Feburary, must be before 29
                if (day > 29) return false;
                // if it's a leap year, can be 29
                if (day == 29 && (year % 4 != 0 || (year % 100 == 0 && year % 400 != 0))) return false;
            } else if (month == 4 || month == 6 || month == 9 || month == 11) {
                // April, June, September, November, must be before 30
                if (day > 30) return false;
            }
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
}

