class Solution {
    public int search(List<Integer> lst) {
    int index = -1;
        int val = 0;
        int count = 0;
        // find the most repeated element
        for (int i = 0; i < lst.size(); i++) {
            count = Collections.frequency(lst, lst.get(i));
            if (count > val) {
                val = count;
                index = i;
            }
        }
        if (val >= lst.get(index)) {
            return lst.get(index);
        }
        return -1;
}

