            count.put(lst.get(i), count.getOrDefault(lst.get(i), 0) + 1);
        }
        // Iterate through the list again and keep track of the max value.
        // If the current value exists in the mapping of numbers to frequencies
        // and it's frequency is greater than or equal to the current value,
        // update the max value.
        int max = -1;
        for (int i = 0; i < lst.size(); i++) {
            if (count.containsKey(lst.get(i)) && count.get(lst.get(i)) >= lst.get(i)) {
                max = Math.max(max, lst.get(i));
            }
        }
        return max;
}

