class Solution {
    public int search(List<Integer> lst) {
    // Find the frequency of each element in the list.
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int i = 0; i < lst.size(); i++) {
            if (frequency.containsKey(lst.get(i))) {
                int currentFreq = frequency.get(lst.get(i));
                frequency.put(lst.get(i), currentFreq + 1);
            } else {
                frequency.put(lst.get(i), 1);
            }
        }
        // Create a new list of pairs containing the element and its frequency.
        ArrayList<Pair<Integer, Integer>> pairs = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
            pairs.add(new Pair<>(entry.getKey(), entry.getValue()));
        }
        // Sort the pairs from smallest to largest frequency.
        Collections.sort(pairs, new Comparator<Pair<Integer, Integer>>() {
            @Override
            public int compare(Pair<Integer, Integer> o1, Pair<Integer, Integer> o2) {
                return o1.getValue1().compareTo(o2.getValue1());
            }
        });
        // Find the smallest key with a frequency greater than or equal to the key.
        for (int i = 0; i < pairs.size(); i++) {
            int key = pairs.get(i).getValue0();
            int freq = pairs.get(i).getValue1();
            if (freq >= key) {
                return key;
            }
        }
        return -1;
}

