class Solution {
    public int startsOneEnds(int n) {
    // How many numbers in [0, 10^n) start with 1?
        // This is 10^(n-1).
        // Now how many numbers in [0, 10^n) end with 1?
        // This is 9 * 10^(n-1).
        // Now we need to subtract out the numbers in [0, 10^n) that start and
        // end with 1.
        // This is 10^(n-2).
        // The answer is 10^(n-1) + 9 * 10^(n-1) - 10^(n-2).
        return (int)Math.pow(10, n-1) + 9 * (int)Math.pow(10, n-1) - (int)Math.pow(10, n-2);
}

