class Solution {
    public int startsOneEnds(int n) {
    if (n < 1) return 0;
        // Dynamic Programming
        // dp[i] -> count of numbers of i-digit positive integers that start or end with 1
        int[] dp = new int[n + 1];
        // base case
        dp[1] = 2;
        // induction hypothesis
        // dp[n] = dp[n - 1] + dp[n - 2]
        for (int i = 2; i <= n; i++) {
            dp[i] = dp[i - 1] + dp[i - 2];
        }
        return dp[n];
}

