class Solution {
    public int startsOneEnds(int n) {
    if (n == 1) return 1;
        // Let x1, x2, ... xn be the digits.
        // For starts with 1, x1 must be 1 and x2, ... xn can be any
        // number (except 0). This can be represented as
        // f(n) = 1 * 9 * 9 * 9 * ... * 9 + f(n - 1).
        // For ends with 1, xn must be 1 and x1, ... xn-1 can be any
        // number. This can be represented as
        // f(n) = 9 * 9 * 9 * ... * 9 + f(n - 1).
        int count = 0;
        int power = 1;
        for (int i = 0; i < n; i++) power *= 9;
        for (int i = 0; i < n; i++) {
            count += 2 * power;
            power /= 9;
        }
        return count;
}

