        int left = 0;
        int right = l.size() - 1;
        while (left < right) {
            if (l.get(left) > l.get(left + 1)) {
                // Decreasing
                while (left < right) {
                    if (l.get(left) < l.get(left + 1)) return false;
                    left += 1;
                }
            } else if (l.get(left) < l.get(left + 1)) {
                // Increasing
                while (left < right) {
                    if (l.get(left) > l.get(left + 1)) return false;
                    left += 1;
                }
            } else {
                // Equal
                left += 1;
            }
        }
        return true;
}

