import java.util.*;
import java.lang.*;

class Solution {
    public String intToMiniRoman(int number) {
    assert(number >= 1 && number <= 1000);
        var result = new StringBuilder();
        var numeralMap = Map.of(1, "i", 5, "v", 10, "x", 50, "l", 100, "c", 500, "d", 1000, "m");
        int currentPlace = 0;
        while (number > 0) {
            int currentDigit = number % 10;
            var currentRomanDigit = new StringBuilder();
            if (currentDigit == 9) {
                currentRomanDigit.append(numeralMap.get(1 * (int) Math.pow(10, currentPlace)));
                currentRomanDigit.append(numeralMap.get(1 * (int) Math.pow(10, currentPlace + 1)));
            } else if (currentDigit == 4) {
                currentRomanDigit.append(numeralMap.get(1 * (int) Math.pow(10, currentPlace)));
                currentRomanDigit.append(numeralMap.get(5 * (int) Math.pow(10, currentPlace)));
            } else {
                if (currentDigit >= 5) {
                    currentRomanDigit.append(numeralMap.get(5 * (int) Math.pow(10, currentPlace)));
                    currentDigit -= 5;
                }
                for (int j = 0; j < currentDigit; j++) {
                    currentRomanDigit.append(numeralMap.get(1 * (int) Math.pow(10, currentPlace)));
                }
            }
            result.insert(0, currentRomanDigit);
            number /= 10;
            currentPlace++;
        }
        return result.toString();
}

