import java.util.*;
import java.lang.*;

class Solution {
    public String intToMiniRoman(int number) {
    StringBuilder builder = new StringBuilder();
        int[] numerals = {100, 10, 1};
        String[] chars = {"c", "x", "i"};
        int[] places = {1, 10, 100};
        for (int i = 0; i < numerals.length; i++) {
            int remainder = number % numerals[i];
            int times = (number - remainder) / numerals[i];
            switch (times) {
                case 9:
                    builder.append(chars[i + 1] + chars[i - 1]);
                    break;
                case 4:
                    builder.append(chars[i + 1] + chars[i]);
                    break;
                default:
                    for (int j = 0; j < times; j++) {
                        builder.append(chars[i]);
                    }
                    break;
            }
            number = remainder;
        }
        return builder.toString();
}

