class Solution {
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
    // Let's say we have two numbers a and b.
        // Let's suppose we already know that a < b.
        // If a - b < threshold, then a < b - threshold.
        // If a - b > threshold, then a > b - threshold.
        // Therefore, if b is closer to a than threshold,
        // then b is closer to a than a - threshold.
        // This allows us to find the closeness by sorting.
        numbers.sort(Comparator.naturalOrder());
        int length = numbers.size();
        for (int i = 0; i < length - 1; i++) {
            float a = numbers.get(i);
            float b = numbers.get(i + 1);
            if (b < a - threshold) {
                return true;
            }
        }
        return false;
}

