class Solution {
    public List<Object> reverseDelete(String s, String c) {
    // We will iterate over the second string and then we will go over the first string
        // and build a string without the characters in the second string.
        // In the end we will check if the built string is palindrome.
        // Let's assume that the length of the second string is q.
        // So the complexity of this algorithm is O(n * q).
        StringBuilder result = new StringBuilder();
        // Iterating over the second string
        for (int i = 0; i < s.length(); i++) {
            char character = s.charAt(i);
            if (c.indexOf(character) == -1) {
                result.append(character);
            }
        }
        // Checking if the string is palindrome
        // We will iterate over the first and the last character and check if they are equal.
        // The complexity of this algorithm is O(n / 2).
        for (int i = 0; i < result.length() / 2; i++) {
            char first = result.charAt(i);
            char last = result.charAt(result.length() - i - 1);
            if (first != last) {
                return new Pair<>(result.toString(), false);
            }
        }
        return new Pair<>(result.toString(), true);
}

