class Solution {
    public List<Integer> sortArray(List<Integer> arr) {
    ArrayList<Pair<Integer, Integer>> pairs = new ArrayList<>();
        for (int i = 0; i < arr.size(); i++) {
            String s = Integer.toBinaryString(arr.get(i));
            int cnt = 0;
            for (int j = 0; j < s.length(); j++)
                if (s.charAt(j) == '1')
                    cnt++;
            pairs.add(new Pair<>(cnt, arr.get(i)));
        }
        pairs.sort((a, b) -> {
            if (a.getValue0() < b.getValue0())
                return -1;
            else if (a.getValue0() > b.getValue0())
                return 1;
            else {
                if (a.getValue1() < b.getValue1())
                    return -1;
                else if (a.getValue1() > b.getValue1())
                    return 1;
                else
                    return 0;
            }
        });
        for (int i = 0; i < arr.size(); i++)
            arr.set(i, pairs.get(i).getValue1());
        return arr;
}

