        while (arr.size() > 0) {
            int min = arr.get(0);
            int min_index = 0;
            for (int i = 1; i < arr.size(); i++) {
                int ones = countOnes(arr.get(i));
                if (countOnes(min) > ones) {
                    min = arr.get(i);
                    min_index = i;
                } else if (countOnes(min) == ones) {
                    if (min > arr.get(i)) {
                        min = arr.get(i);
                        min_index = i;
                    }
                }
            }
            result.add(min);
            arr.remove(min_index);
        }
        return result;
}

