class Solution {
    public List<Integer> sortArray(List<Integer> arr) {
    ArrayList<Integer> sorted = new ArrayList<Integer>();
        ArrayList<Integer> sortedIndices = new ArrayList<Integer>();
        ArrayList<Integer> zeroBits = new ArrayList<Integer>();
        ArrayList<Integer> zeroBitsIndices = new ArrayList<Integer>();
        for (int i = 0; i < arr.size(); i++) {
            int zeroCount = 0;
            int num = arr.get(i);
            while (num > 0) {
                if (num % 2 == 0) {
                    zeroCount++;
                }
                num /= 2;
            }
            if (zeroCount == 0) {
                sorted.add(arr.get(i));
                sortedIndices.add(i);
            } else {
                zeroBits.add(zeroCount);
                zeroBitsIndices.add(i);
            }
        }
        for (int i = 0; i < zeroBits.size(); i++) {
            for (int j = i + 1; j < zeroBits.size(); j++) {
                if (zeroBits.get(i) > zeroBits.get(j)) {
                    int temp = zeroBits.get(i);
                    zeroBits.set(i, zeroBits.get(j));
                    zeroBits.set(j, temp);
                    temp = zeroBitsIndices.get(i);
                    zeroBitsIndices.set(i, zeroBitsIndices.get(j));
                    zeroBitsIndices.set(j, temp);
                }
            }
        }
        for (int i = 0; i < zeroBits.size(); i++) {
            sorted.add(arr.get(zeroBitsIndices.get(i)));
            sortedIndices.add(zeroBitsIndices.get(i));
        }
        ArrayList<Integer> out = new ArrayList<Integer>();
        for (int i = 0; i < arr.size(); i++) {
            out.add(arr.get(sortedIndices.get(i)));
        }
        return out;
}

