class Solution {
    public List<Integer> sortArray(List<Integer> array) {
    int len = array.size();
        int i = 0;
        int j = len - 1;
        int first = array.get(i);
        int last = array.get(j);
        boolean isOdd = (first + last) % 2 == 1;
        // System.out.println(isOdd);
        ArrayList<Integer> ans = new ArrayList<Integer>();
        while (i < j) {
            if (isOdd) {
                if (array.get(i) > array.get(j)) {
                    ans.add(array.get(i));
                    i++;
                } else {
                    ans.add(array.get(j));
                    j--;
                }
            } else {
                if (array.get(i) < array.get(j)) {
                    ans.add(array.get(i));
                    i++;
                } else {
                    ans.add(array.get(j));
                    j--;
                }
            }
        }
        if (i == j) {
            ans.add(array.get(i));
        }
        Collections.reverse(ans);
        return ans;
}

