class Solution {
    public String wordsInSentence(String sentence) {
    // Given a string, the sentence.
        // Split the string into words by whitespace.
        String[] words = sentence.split("\\s+");
        // Assume a prime number.
        int isPrime = 1;
        // Assume the input string is empty.
        String result = "";
        // Iterate over all words in the string.
        for (int i = 0; i < words.length; i++) {
            // Calculate the length of the word.
            int length = words[i].length();
            // Iterate over all numbers from 2 to n - 1.
            for (int j = 2; j < length; j++) {
                // If n is divisible by j, assume n is not prime.
                if (length % j == 0) {
                    isPrime = 0;
                    break;
                }
            }
            // If the number is prime,
            // add the current word to the result string.
            if (isPrime == 1) {
                result += words[i] + " ";
            }
            // Assume a prime number for the next word.
            isPrime = 1;
        }
        // Return the result string.
        return result;
}

