class Solution {
    public int largestDivisor(int n) {
    // prime factorization using a sieve
        boolean[] primes = new boolean[n];
        Arrays.fill(primes, true);
        for (int i = 2; i < n; i++) {
            if (primes[i]) {
                for (int j = i * 2; j < n; j += i) {
                    primes[j] = false;
                }
            }
        }
        // if n is prime, return 1
        if (primes[n]) return 1;
        // otherwise, return the largest prime factor
        for (int i = n - 1; i >= 2; i--) {
            if (primes[i] && n % i == 0) return i;
        }
        return 1;
}

