class Solution {
    public String matchParens(List<String> lst) {
    String str1 = lst.get(0);
        String str2 = lst.get(1);
        int x = str1.length();
        int y = str2.length();
        int dp[][] = new int[x + 1][y + 1];
        for (int i = 0; i <= x; i++) {
            for (int j = 0; j <= y; j++) {
                if (i == 0 && j == 0) {
                    dp[i][j] = 0;
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + 1;
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + 1;
                } else {
                    dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1]) + 1;
                }
            }
        }
        if (dp[x][y] == 0) {
            return "Yes";
        } else {
            return "No";
        }
}

