        HashSet<String> vowelSet = new HashSet<String>(Arrays.asList(vowels));
        HashSet<String> consonantSet = new HashSet<String>(Arrays.asList(consonants));
        int min = word.length();
        String result = empty;
        int wordLength = word.length();
        if (wordLength <= 2) return empty;
        int index = wordLength - 1;
        while (index >= 0) {
            String letter = word.substring(index, index + 1);
            int distance = wordLength - index;
            if (vowelSet.contains(letter)) {
                if (distance < min) {
                    min = distance;
                    result = letter;
                }
            }
            index--;
        }
        return result;
}

