class Solution {
    public boolean isSorted(List<Integer> lst) {
    // Given an arraylist of numbers as input, return true if the list is
        // sorted, false otherwise.
        // Assume lst is NOT empty, and there are no negative numbers.
        // Assume that an array list that is all equal values is NOT sorted.
        // Assume the array only contains integers, no decimals.
        // Assume that duplicates of the same number are sorted only if the
        // duplicates are in sequential order.
        // Assume that the list is not empty.
        // Assume that the list will not have more than 100 elements.
        // Assume that the list does not have null elements.
        if (lst.size() == 1) {
            return true;
        }
        else {
            Integer prev = lst.get(0);
            for (int i = 1; i < lst.size(); i++) {
                if (lst.get(i) < prev) {
                    return false;
                }
                else {
                    prev = lst.get(i);
                }
            }
            return true;
        }
}

