    public boolean isSorted(List<Integer> lst) {
    boolean isSorted = true;
        ArrayList<Integer> lstCopy = new ArrayList<Integer>(lst);
        Collections.sort(lstCopy);
        int count = 0;
        for (int i = 0; i < lst.size(); i++) {
            int lstCopyInt = lstCopy.get(i);
            int lstInt = lst.get(i);
            if (lstCopyInt != lstInt) {
                isSorted = false;
            }
            for (int j = 0; j < lst.size(); j++) {
                if (lstCopyInt == lst.get(j)) {
                    count++;
                }
            }
            if (count > 1) {
                isSorted = false;
            }
            count = 0;
        }
        return isSorted;
}

