        // Since a[i] = i * i - i + 1, and a[i] is an integer, we need i^2 >= 3i + 2.
        // That is i >= (3 + sqrt(9 - 8)) / 2 ~= 1.9.
        // As n >= 4, we can safely assume i >= 2.
        int count = 0;
        for (int i = 2; i < n; i++) {
