class Solution {
    public int getMaxTriples(int n) {
    if (n <= 2) return 0;
        List<Integer> nums = new ArrayList<>();
        for (int i = 1; i <= n; i++) nums.add(i * i - i + 1);
        Collections.sort(nums);
        int max = 0;
        int total = 0;
        for (int i = 0; i < nums.size() - 2; i++) {
            int a = nums.get(i);
            int lo = i + 1;
            int hi = nums.size() - 1;
            while (lo < hi) {
                int b = nums.get(lo);
                int c = nums.get(hi);
                int sum = a + b + c;
                if (sum % 3 == 0) {
                    max = Math.max(max, sum);
                    total++;
                    lo++;
                    hi--;
                } else if (sum % 3 == 1) lo++;
                else hi--;
            }
        }
        return total;
}

