class Solution {
    public int getMaxTriples(int n) {
    if (n < 3) {
            return 0;
        }
        long[][] dp = new long[n + 1][n + 1];
        long[] array = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            array[i] = i * i - i + 1;
        }
        int count = 0;
        for (int i = 1; i <= n; i++) {
            int tmp = 0;
            for (int j = 1; j <= n; j++) {
                if (i == j) {
                    continue;
                }
                if ((array[i] + array[j]) % 3 == 0) {
                    dp[i][j] = 1;
                    tmp += 1;
                }
            }
            for (int j = 1; j <= n; j++) {
                if (i == j) {
                    continue;
                }
                for (int k = 1; k <= n; k++) {
                    if (i == k || j == k) {
                        continue;
                    }
                    if ((array[i] + array[j] + array[k]) % 3 == 0) {
                        dp[i][j] += dp[j][k];
                    }
                }
                count += tmp * dp[i][j];
            }
        }
        return count;
}

