import java.util.*;
import java.lang.*;

class Solution {
    public int getMaxTriples(int n) {
    int count = 0;
        // a[i] is strictly increasing, so all pairs i and j with i < j that a[i] + a[j] % 3 == 0
        // will be counted.
        // Given any i, the smallest j for which a[i] + a[j] is a multiple of 3 is j = i + i % 3 + 1
        // The largest j for which a[i] + a[j] is a multiple of 3 is given by j = n - (n - 1 - i) % 3.
        // For example, consider i = 2 and n = 5:
        // a[2] = 7, a[2] + a[3] = 10, a[2] + a[4] = 18. The only j for which a[2] + a[j] is a multiple of 3 is 4.
        // The largest j such that i < j and a[i] + a[j] is a multiple of 3 is 4.
        // This means that 7 (a[2]) + the values of a[i] with i < 4 form 4 pairs that are multiples of 3.
        // The number of pairs that 7 forms with values of a[i] with i < 4 is 3 (i.e. when i = 3, 4, 5).
        // Thus the number of pairs that are multiples of 3 is (4 - 2) + (3 - 2) = 4.
        // The count is incremented by 4, and the loop continues with i = 3.
        // The final count is 5.
        // Since i is incremented by one each time, the smallest j is equal to i + i % 3 + 1.
        // Since j is decremented by one each time, the largest j is equal to n - (n - 1 - i) % 3.
        for (int i = 1; i < n; i++) {
            int j = i + i % 3 + 1;
            for (; j <= n - (n - 1 - i) % 3; j++) {
                count++;
            }
        }
        return count;
}

