    public int addElements(List<Integer> arr, int k) {
    // We'll just do an O(n) traversal on arr
        // if arr[i] < 100 then we can add it to the sum
        // if arr[i] >= 100 then we shouldn't because it's more than 2 digits
        // if arr[i] < 10 then we should add it to the sum
        // if i >= k then we should break out of the loop
        int result = 0;
        for (int i = 0; i < arr.size(); i++) {
            if (arr.get(i) < 100 && arr.get(i) >= 10) {
                result += arr.get(i);
            }
            if (i >= k) {
                break;
            }
        }
        return result;
}

