class Solution {
    public int chooseNum(int x, int y) {
    // The number of even numbers in the range [x, y] inclusive is:
        // num_even = (y - x + 1)/2
        // The biggest even number in the range [x, y] inclusive is:
        // num_biggest = x + 2*(num_even - 1)
        // Proof: Say we have x = 12, y = 14.
        // The number of even numbers in [12, 14] is 2.
        // The biggest even number in [12, 14] is 12 + 2*(2 - 1) = 14.
        // Say we have x = 12, y = 15.
        // The number of even numbers in [12, 15] is 3.
        // The biggest even number in [12, 15] is 12 + 2*(3 - 1) = 16.
        // Say we have x = 12, y = 16.
        // The number of even numbers in [12, 16] is 4.
        // The biggest even number in [12, 16] is 12 + 2*(4 - 1) = 18.
        int num_even = (y - x + 1)/2;
        int num_biggest = x + 2*(num_even - 1);
        if (num_even == 0) {
            return -1;
        } else {
            return num_biggest;
        }
}

