class Solution {
    public int primeFib(int n) {
    if (n < 1)
            throw new IllegalArgumentException("n should be greater than or equal to 1");
        ArrayList<Integer> fibs = new ArrayList<Integer>();
        fibs.add(2);
        fibs.add(3);
        int i = 2;
        while (fibs.size() < n) {
            BigInteger next = BigInteger.valueOf(fibs.get(i - 1)).add(BigInteger.valueOf(fibs.get(i - 2)));
            if (next.isProbablePrime(16))
                fibs.add(next.intValue());
            i += 1;
        }
        return fibs.get(n - 1);
}

