class Solution {
    public boolean isEqualToSumEven(int n) {
    boolean isPossible = false;
        List<Integer> evenNumbers = new ArrayList<>();
        // find all numbers that are less than n and are even
        for (int i = 2; i < n; i++) {
            if (i % 2 == 0) {
                evenNumbers.add(i);
            }
        }
        List<int[]> pairs = new ArrayList<>();
        // find pairs of even numbers that add up to less than n
        for (int i = 0; i < evenNumbers.size(); i++) {
            for (int j = i + 1; j < evenNumbers.size(); j++) {
                if (evenNumbers.get(i) + evenNumbers.get(j) < n) {
                    pairs.add(new int[]{evenNumbers.get(i), evenNumbers.get(j)});
                }
            }
        }
        // check whether each even number can be divided into a sum of three pairs
        for (int i = 0; i < evenNumbers.size(); i++) {
            int evenNumber = evenNumbers.get(i);
            int sum = 0;
            int pairIndex = 0;
            boolean found = false;
            // go through each pair, and see if the sum of three pairs equals the current even number
            while (pairIndex < pairs.size() && !found) {
                sum = 0;
                for (int[] pair : pairs) {
                    sum += pair[0] + pair[1];
                    if (sum == evenNumber) {
                        found = true;
                        break;
                    }
                }
                pairIndex++;
            }
            if (found) {
                isPossible = true;
                break;
            }
        }
        return isPossible;
}

