class Solution {
    public boolean isEqualToSumEven(int n) {
    if (n < 0) {
            throw new RuntimeException("Input has to be positive");
        }

        int k = 4;

        if (n % 2 != 0) {
            return false;
        }

        n = n / 2;

        // dynamic programming
        boolean[][] dp = new boolean[n + 1][k + 1];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                if (j == 0) {
                    dp[i][j] = true;
                } else if (i < j) {
                    dp[i][j] = false;
                } else if (j == 1) {
                    dp[i][j] = i % 2 == 0;
                } else {
                    dp[i][j] = (dp[i - 2][j - 1] || dp[i - 1][j]);
                }
            }
        }

        return dp[n][k];
}

