class Solution {
    public boolean sameChars(String s0, String s1) {
    // 3. Count the number of each letter in s0.
        Map<Character, Integer> counts0 = new HashMap<>();
        for (int i = 0; i < s0.length(); i++) {
            char c = s0.charAt(i);
            if (counts0.containsKey(c)) {
                counts0.put(c, counts0.get(c) + 1);
            } else {
                counts0.put(c, 1);
            }
        }
        // counts0:
        // { 'a': 1, 'b': 1, 'c': 1, 'd': 1, 'e': 1, 'z': 4 }
        // 4. Loop through the letters in s1.
        for (int i = 0; i < s1.length(); i++) {
            char c = s1.charAt(i);
            // 5. If the letter isn't in s0, return False.
            if (!counts0.containsKey(c)) {
                return false;
            }
            // 6. Decrement the count in counts0.
            int count = counts0.get(c);
            if (count == 1) {
                counts0.remove(c);
            } else {
                counts0.put(c, count - 1);
            }
        }
        // 7. Return True if counts0 is empty.
        return counts0.isEmpty();
}

