        int sum0 = 0;
        for (int i = 0; i < s0.length(); i++) {
            sum0 += s0.charAt(i);
        }
        int sum1 = 0;
        for (int i = 0; i < s1.length(); i++) {
            sum1 += s1.charAt(i);
        }
        // then subtract the ord values of s0 from s1
        // then sum the ord values of the characters left
        if (sum0 == sum1) {
            return true;
        }
        int sum2 = 0;
        for (int i = 0; i < s1.length(); i++) {
            sum2 += s1.charAt(i) - s0.charAt(i);
        }
        // if sum2 == sum0 the two word have the same characters.
        if (sum2 == sum0) {
            return true;
        }
        return false;
}

