            return "No";
        if (length < 3)
            return "No";
        if (file_name.charAt(length - 1) == '.')
            return "No";
        for (int i = 0; i < length; i++) {
            char c = file_name.charAt(i);
            if (c >= '0' && c <= '9')
                digitCount++;
            if (c == '.')
                dotCount++;
        }
        if (digitCount > 3 || dotCount != 1)
            return "No";
        if (file_name.indexOf('.') == length - 1)
            return "No";
        String suffix = file_name.substring(file_name.indexOf('.') + 1);
        if (suffix.equals("txt") || suffix.equals("exe") || suffix.equals("dll"))
            return "Yes";
        return "No";
}

