class Solution {
    public boolean cycpatternCheck(String a, String b) {
    if (a.length() == 0 || b.length() == 0) return false;
        // convert b to a list of chars
        char[] bChars = b.toCharArray();
        // loop from 0 to b.length
        for (int i = 0; i < b.length(); i++) {
            // push back the first element in the list and rotate the list to the left
            char temp = bChars[0];
            for (int j = 0; j < bChars.length - 1; j++) {
                bChars[j] = bChars[j + 1];
            }
            bChars[bChars.length - 1] = temp;
            // check if the rotated list is a substring of a
            String c = new String(bChars);
            if (a.contains(c)) return true;
        }
        return false;
}

