        char[] aArr = a.toCharArray();
        char[] bArr = b.toCharArray();
        for (int i = 0; i < b.length(); i++) {
            hash[aArr[i] - 'a']++;
            rotHash[bArr[i] - 'a']++;
        }
        if (Arrays.equals(hash, rotHash)) {
            return true;
