    // f0 = 0
        // f1 = 0
        // f2 = 2
        // f3 = 0
        // f4 = f0 + f1 + f2 + f3
        // f5 = f1 + f2 + f3 + f4
        // f6 = f2 + f3 + f4 + f5
        // f7 = f3 + f4 + f5 + f6
        // f8 = f4 + f5 + f6 + f7
        // f9 = f5 + f6 + f7 + f8
        // f10 = f6 + f7 + f8 + f9
        // f11 = f7 + f8 + f9 + f10
        // f12 = f8 + f9 + f10 + f11
        // f13 = f9 + f10 + f11 + f12
        // f14 = f10 + f11 + f12 + f13
        // f15 = f11 + f12 + f13 + f14
        // f16 = f12 + f13 + f14 + f15
        // ...
        // fk = f(k-4) + f(k-3) + f(k-2) + f(k-1)
        int a = 0;
        int b = 0;
        int c = 2;
        int d = 0;
        int fk = 0;
        if (n == 0) {
            return a;
        } else if (n == 1) {
            return b;
        } else if (n == 2) {
            return c;
        } else if (n == 3) {
            return d;
        } else {
            for (int i = 0; i < n - 3; i++) {
                fk = a + b + c + d;
                a = b;
                b = c;
                c = d;
                d = fk;
            }
            return fk;
        }
}

