        if (paren_string.charAt(i) == '(') {
          int j = i + 1;
          int count = 1;
          while (j < paren_string.length() && count > 0) {
            if (paren_string.charAt(j) == '(') {
              count += 1;
            } else if (paren_string.charAt(j) == ')') {
              count -= 1;
            }
            j += 1;
          }
          if (count == 0) {
            result.add(paren_string.substring(i, j));
            last_index = j;
          }
        }
        i += 1;
      }
