class Solution {
    public List<Integer> evenOddPalindrome(int n) {
    // 1. Check whether the input is valid
        if (n < 1 || n > Math.pow(10, 3)) {
            throw new IllegalArgumentException("Not a valid input");
        }
        // 2. Construct the list of integers from 1 to n
        List<Integer> list = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            list.add(i);
        }
        // 3. Filter the list
        List<Integer> even = list.stream().filter(ele -> ele % 2 == 0).collect(Collectors.toList());
        List<Integer> odd = list.stream().filter(ele -> ele % 2 != 0).collect(Collectors.toList());
        // 4. Count the number of palindromes
        int evenCount = 0;
        int oddCount = 0;
        for (int i = 0; i < even.size(); i++) {
            String str = Integer.toString(even.get(i));
            StringBuilder sb = new StringBuilder(str);
            if (str.equals(sb.reverse().toString())) {
                evenCount++;
            }
        }
        for (int i = 0; i < odd.size(); i++) {
            String str = Integer.toString(odd.get(i));
            StringBuilder sb = new StringBuilder(str);
            if (str.equals(sb.reverse().toString())) {
                oddCount++;
            }
        }
        // 5. Return the result
        return new Pair<Integer, Integer>(evenCount, oddCount);
}

