    // first find the largest prime number
        HashSet<Integer> primes = new HashSet<Integer>();
        for (int i = 0; i < lst.size(); i++) {
            int num = lst.get(i);
            if (isPrime(num)) {
                primes.add(num);
            }
        }
        // now return the sum of the digits in that number
        int val = 0;
        // find the largest prime
        for (int num : primes) {
            if (num > val) {
                val = num;
            }
        }
        // we have the largest number, we need to sum it
        int rtn = 0;
        while (val > 0) {
            rtn += val % 10;
            val /= 10;
        }
        return rtn;
}

