class Solution {
    public List<Integer> orderByPoints(List<Integer> nums) {
    ArrayList<Pair<Integer, Integer>> l = new ArrayList<>();
        for (int i = 0; i < nums.size(); i++) {
            int n = nums.get(i);
            int s = n >= 0 ? n : -n;
            int sum = 0;
            while (s > 0) {
                sum += s % 10;
                s /= 10;
            }
            l.add(new Pair<>(sum, n));
        }
        Collections.sort(l, (a, b) -> {
            if (a.getValue0() != b.getValue0())
                return a.getValue0() - b.getValue0();
            return a.getValue1() - b.getValue1();
        });
        ArrayList<Integer> res = new ArrayList<>();
        for (Pair<Integer, Integer> p : l)
            res.add(p.getValue1());
        return res;
}

