class Solution {
    public String encode(String message) {
    StringBuilder sb = new StringBuilder();
        String vowels = "aeiou";
        //loop through each character
        for (int i = 0; i < message.length(); i++) {
            char curr = message.charAt(i);
            //if the current char is a letter, swap case and add to the stringbuilder
            if (Character.isLetter(curr)) {
                char c = Character.isUpperCase(curr) ? Character.toLowerCase(curr) : Character.toUpperCase(curr);
                //if the current char is a vowel, encode it and add to the stringbuilder
                if (vowels.indexOf(c) != -1) {
                    //get the index of the current char in the vowels string
                    int index = vowels.indexOf(c);
                    //get the next two indices, mod by the length of the string so that we can wrap around
                    int nextIndex = (index + 2) % vowels.length();
                    int nextNextIndex = (index + 4) % vowels.length();
                    //get the character at the next two indices, swap case and add to the stringbuilder
                    char nextChar = Character.isUpperCase(c) ? Character.toUpperCase(vowels.charAt(nextIndex)) : Character.toLowerCase(vowels.charAt(nextIndex));
                    char nextNextChar = Character.isUpperCase(c) ? Character.toUpperCase(vowels.charAt(nextNextIndex)) : Character.toLowerCase(vowels.charAt(nextNextIndex));
                    sb.append(nextChar);
                    sb.append(nextNextChar);
                } else {
                    sb.append(c);
                }
            } else {
                sb.append(curr);
            }
        }
        return sb.toString();
}

