class Solution {
    public int carRaceCollision(int n) {
    // Invariant:
        // no_of_collisions[i] represents the number of collisions before i + 1-th car
        // moving left to right gets started.  This will be used to compute the
        // number of collisions before the ith car moving left to right gets started.
        // Note: no_of_collisions[0] = 0
        int[] no_of_collisions = new int[n];
        // Note: There are n cars moving left to right; let's call these cars
        // car_1, car_2, ..., car_n.  We know that car_1 started first, followed by
        // car_2 and so on.  So the ith car moving left to right started t_i seconds
        // after car_1 started, where t_i = i - 1.
        // Now, suppose car_i collides with car_j moving right to left.  This means
        // that car_i overtook car_j.  However, car_i started only t_i seconds
        // after car_1 started, and car_j started only t_j seconds after car_1 started.
        // Therefore, car_i should have overtaken car_j t_i - t_j = i - j seconds
        // after car_1 started.  Now, car_i and car_j are infinitely strong, so they
        // continue moving and hence we say that a collision took place.
        // (Note: if i < j, then i - j < 0 and so car_i should have overtaken car_j before
        // car_1 got started.  However, this is impossible.)
        // Therefore, the total number of collisions between the ith car moving left to right
        // and the cars moving right to left is equal to the number of j such that 0 < j < i and
        // i - j = 0.  This is equal to i - 1.
        for (int i = 1; i < n; i++) {
            no_of_collisions[i] = no_of_collisions[i - 1] + i - 1;
        }
        return no_of_collisions[n - 1];
}

