class Solution {
    public List<String> numericalLetterGrade(List<Double> grades) {
    String[] gradesArray = {"A+", "A", "A-", "B+", "B", "B-", "C+", "C", "C-", "D+", "D", "D-", "E"};
        int[] correspondingGPAs = {400, 370, 330, 300, 270, 230, 200, 170, 130, 100, 70, 0};
        int[] gradesPoints = new int[grades.size()];
        for (int i = 0; i < grades.size(); i++) {
            float grade = grades.get(i);
            if (grade < 1) {
                gradesPoints[i] = 0;
            } else {
                gradesPoints[i] = (int) (100 * (grade - 1) + 1);
            }
        }
        ArrayList<String> letterGrades = new ArrayList<String>();
        for (int i = 0; i < gradesPoints.length; i++) {
            int grade = gradesPoints[i];
            if (grade == 400) {
                letterGrades.add(gradesArray[0]);
            } else {
                for (int j = 1; j < correspondingGPAs.length; j++) {
                    if (grade > correspondingGPAs[j]) {
                        letterGrades.add(gradesArray[j]);
                        break;
                    }
                }
            }
        }
        return letterGrades;
}

