    public List<Integer> parseNestedParens(String paren_string) {
    ArrayList<Integer> depths = new ArrayList<Integer>();
        // Fill this in.
        // Initialize our stack
        Stack<Character> stack = new Stack<Character>();
        // For each parentheses string
        for (String paren_str : paren_string.split(" ")) {
            // For each parentheses character
            for (int i = 0; i < paren_str.length(); i++) {
                // Push opening parentheses to the stack
                if (paren_str.charAt(i) == '(') {
                    stack.push(paren_str.charAt(i));
                }
                // Pop closing parentheses from the stack
                else if (paren_str.charAt(i) == ')') {
                    stack.pop();
                }
            }
            // Add maximum depth of nested parentheses to the result
            depths.add(stack.size());
            // Clear the stack
            stack.clear();
        }
        return depths;
}

