            // set j and k to a subsequent element after i
            j = i + 1;
            k = i + 2;
            // iterate through the array
            for (; j < array.length; j++) {
                // start k at the next subsequent element after j
                k = j + 1;
                // iterate through the array
                for (; k < array.length; k++) {
                    // if the sum of the three pointers is equal to zero, return true
                    if (array[i] + array[j] + array[k] == 0) {
                        return true;
                    }
                }
            }
        }
