        switch (op.get(i)) {
          case "+":
            val += operand.get(i + 1);
            break;
          case "-":
            val -= operand.get(i + 1);
            break;
          case "*":
            val *= operand.get(i + 1);
            break;
          case "//":
            val /= operand.get(i + 1);
