import java.util.*;
import java.lang.*;

class Solution {
    public int greatestCommonDivisor(int a, int b) {
    if (a == 0) return b;
        if (b == 0) return a;
        int gcd = 0;
        while (a % 2 == 0 && b % 2 == 0) {
            a /= 2;
            b /= 2;
            gcd++;
        }
        while (a != b) {
            if (a % 2 == 0) a /= 2;
            else if (b % 2 == 0) b /= 2;
            else if (a > b) a = (a - b) / 2;
            else b = (b - a) / 2;
        }
        return a * (int) Math.pow(2, gcd);
}

