            for (int len = 1; len <= end; len++) {
                // Test whether string[end - len + 1, end] is a palindrome.
                if (len <= end && string.charAt(end - len) == string.charAt(end)) {
                    // string[end - len + 1, end] is a palindrome.
                    if (len > max_len) {
                        max_len = len;
                        max_end = end;
                    }
                } else {
                    break;
                }
            }
        }

        // Create the reversed string of string[0, max_end - max_len].
        int cut_start = max_end - max_len + 1;
        int cut_end = max_end + 1;
        String reversed_string = new StringBuilder(string.substring(0, cut_start)).reverse().toString();

        // Return the concatenation of the reversed string and string[cut_end].
        return string.substring(0, cut_end) + reversed_string;
}

