    StringBuilder sb = new StringBuilder(string);
        // rsb holds the string in reverse order.
        StringBuilder rsb = new StringBuilder(string).reverse();
        int n = string.length();
        int[] p = new int[n];
        p[0] = 0;
        int k = 0;
        for (int i = 1; i < n; i++) {
            while (k > 0 && string.charAt(k) != string.charAt(i))
                k = p[k - 1];
            if (string.charAt(k) == string.charAt(i))
                k++;
            p[i] = k;
        }
        // Now we know the length of the longest palindromic suffix.
        int l = p[n - 1];
        // Append all the characters starting from the character l.
        sb.append(rsb.substring(l));
        return sb.toString();
}

