class Solution {
    public Map<String, Integer> histogram(String test) {
    HashMap<String,Integer> res = new HashMap<String,Integer>();
        HashMap<String,Integer> freq = new HashMap<String,Integer>();
        HashMap<Integer,ArrayList<String>> freq_to_key = new HashMap<Integer,ArrayList<String>>();
        int max = -1;
        if (test == null || test.length() == 0) return res;
        String[] words = test.split(" ");
        for (String w : words) {
            if (freq.containsKey(w)) {
                freq.put(w, freq.get(w) + 1);
            } else {
                freq.put(w, 1);
            }
            if (freq.get(w) > max) {
                max = freq.get(w);
            }
        }
        for (String key : freq.keySet()) {
            int value = freq.get(key);
            if (freq_to_key.containsKey(value)) {
                freq_to_key.get(value).add(key);
            } else {
                ArrayList<String> newlist = new ArrayList<String>();
                newlist.add(key);
                freq_to_key.put(value, newlist);
            }
        }
        if (freq_to_key.containsKey(max)) {
            for (String key : freq_to_key.get(max)) {
                res.put(key, max);
            }
        }
        return res;
}

